-- Athena saved query (Product_B2C_Intl)
-- ID: 5a22988b-5565-442a-9083-626e37fc1407
-- Name: Bus Images Dashboard Coverage Android and iOS- Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH sl_deduped AS ( SELECT __time, CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN os = 'iOS' AND app_code >= 859800 THEN mri_session_id END AS mri_session_id, route_id, os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-07-19 18:30:00' AND __time < TIMESTAMP '2026-07-26 18:30:00' AND channel = 'MOBILE_APP' AND country = 'IND' AND status = 200 AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5, 6 UNION ALL SELECT __time, CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, CASE WHEN os = 'Android' AND app_code >= 822000 AND app_code < 999999 THEN mri_session_id END AS mri_session_id, route_id, os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), DATE(doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-07-19 18:30:00' AND __time < TIMESTAMP '2026-07-26 18:30:00' AND channel = 'MOBILE_APP' AND country = 'IND' AND status = 200 AND tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5, 6 ), base AS ( SELECT u.__time, CAST(DATE_TRUNC('day', at_timezone(u.__time, 'Asia/Kolkata')) AS DATE) AS doi, u.event_src channel, u.route_id_train_no route_id, u.mri_session_id, MAX(CASE WHEN u.event_group = 'sl_screen_load' AND u.event_name LIKE '%sl_loaded%' THEN 1 ELSE 0 END) AS overall_sl_loaded, MAX(CASE WHEN u.event_src = 'iOS' AND u.event_group = 'ab_exp_busImage' AND u.event_name = 'NewBusImageLoaded' AND u.app_code >= 859800 THEN 1 WHEN u.event_src = 'Android' AND u.event_group = 'sl_click_info' AND u.event_name = 'NewBusImageLoaded' AND u.app_code >= 822000 AND u.app_code < 999999 THEN 1 ELSE 0 END) AS SL_Load_with_New_Bus_Images FROM "user_interaction"."ui_ux_events" u WHERE __time >= TIMESTAMP '2026-07-19 18:30:00' AND __time < TIMESTAMP '2026-07-26 18:30:00' AND event_src IN ('Android', 'iOS') AND event_group IN ('sl_screen_load', 'ab_exp_busImage', 'sl_click_info') AND (event_name IN ('NewBusImageLoaded') OR event_name LIKE '%sl_loaded%') GROUP BY 1, 2, 3, 4, 5 ) SELECT sl.doi, sl.os channel, sl.dbd DBD, COUNT(DISTINCT CASE WHEN b.overall_sl_loaded = 1 THEN sl.mri_session_id END) AS overall_sl_loaded, COUNT(DISTINCT CASE WHEN b.SL_Load_with_New_Bus_Images = 1 THEN sl.mri_session_id END) AS SL_Load_with_New_Bus_Images FROM base b LEFT JOIN sl_deduped sl ON sl.mri_session_id = b.mri_session_id AND sl.route_id = CAST(b.route_id AS BIGINT) GROUP BY 1, 2, 3 ORDER BY 1, 2, 3
